"""Bounded Python job protocol; generated bytes never enter model context."""

import base64
import io
import zipfile
from dataclasses import dataclass
from typing import Annotated
from uuid import UUID

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

from agentforge_core.attachments import MAX_FILE, filename

PYTHON_TOOL = "python_execute@1"
PPTX_MIME = "application/vnd.openxmlformats-officedocument.presentationml.presentation"
FILE_MIMES = {
    ".pptx": PPTX_MIME,
    ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    ".docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    ".pdf": "application/pdf",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".csv": "text/csv",
    ".txt": "text/plain",
    ".md": "text/markdown",
    ".json": "application/json",
    ".zip": "application/zip",
}
WORKSPACE_FILE_MIMES = {
    **FILE_MIMES,
    ".jpeg": "image/jpeg",
    ".gif": "image/gif",
    ".webp": "image/webp",
    ".html": "text/html",
    ".htm": "text/html",
    ".markdown": "text/markdown",
}
ImageId = Annotated[str, Field(pattern=r"^sha256:[a-f0-9]{64}$")]


def output_name(value, *, workspace=False):
    filename(value)
    mimes = WORKSPACE_FILE_MIMES if workspace else FILE_MIMES
    if len(value) > 128 or not any(value.lower().endswith(suffix) for suffix in mimes):
        raise ValueError("Unsupported output file name")
    return value


class PythonArguments(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    code: str = Field(min_length=1, max_length=15000)
    exports: list[str] = Field(default_factory=list, max_length=4)

    @field_validator("exports")
    @classmethod
    def names(cls, values):
        if len(set(values)) != len(values):
            raise ValueError("Duplicate exports")
        return [output_name(v) for v in values]


class EncodedFile(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    name: str = Field(min_length=1, max_length=128)
    data: str = Field(min_length=4, max_length=14_000_000)


class InputFile(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True, frozen=True)
    artifact_id: str
    name: str = Field(min_length=1, max_length=128)

    @field_validator("artifact_id")
    @classmethod
    def valid_id(cls, value):
        return str(UUID(value))

    @field_validator("name")
    @classmethod
    def valid_name(cls, value):
        filename(value)
        if value.startswith("_agentforge_"):
            raise ValueError("Reserved input name")
        return value


class FileReference(InputFile):
    size: int = Field(gt=0, le=MAX_FILE)
    mime_type: str = Field(max_length=128)
    version: int = Field(default=1, ge=1)


class PythonArgumentsV2(PythonArguments):
    inputs: list[InputFile] = Field(default_factory=list, max_length=4)

    @field_validator("inputs")
    @classmethod
    def unique_inputs(cls, values):
        if len({v.name for v in values}) != len(values):
            raise ValueError("Duplicate input aliases")
        return values


class PythonJob(PythonArguments):
    image: ImageId
    inputs: list[EncodedFile] = Field(default_factory=list, max_length=4)

    @field_validator("inputs")
    @classmethod
    def bounded_inputs(cls, values):
        total = 0
        names = set()
        for item in values:
            InputFile.valid_name(item.name)
            data = base64.b64decode(item.data, validate=True)
            total += len(data)
            if not data or total > MAX_FILE or item.name in names:
                raise ValueError("Invalid input file batch")
            names.add(item.name)
        return values


class PythonResponse(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    exit_code: int = Field(ge=-255, le=255)
    stdout: str = Field(max_length=3000)
    stderr: str = Field(max_length=3000)
    files: list[EncodedFile] = Field(default_factory=list, max_length=4)

    @model_validator(mode="after")
    def failed_exports(self):
        if self.exit_code != 0 and self.files:
            raise ValueError("Failed scripts cannot publish files")
        return self


@dataclass(frozen=True)
class GeneratedFile:
    name: str
    mime_type: str
    data: bytes
    artifact_id: str | None = None
    parent_id: str | None = None
    display_name: str | None = None
    description: str | None = None

    @classmethod
    def decode(cls, encoded, *, workspace=False):
        name = output_name(encoded.name, workspace=workspace)
        data = base64.b64decode(encoded.data, validate=True)
        if not 0 < len(data) <= MAX_FILE:
            raise ValueError("Invalid generated file size")
        suffix = "." + name.rsplit(".", 1)[-1].lower()
        required = {
            ".pptx": "ppt/presentation.xml",
            ".xlsx": "xl/workbook.xml",
            ".docx": "word/document.xml",
        }.get(suffix)
        if required:
            with zipfile.ZipFile(io.BytesIO(data)) as archive:
                entries = archive.infolist()
                if (
                    len(entries) > 512
                    or sum(i.file_size for i in entries) > 40 * 1024 * 1024
                    or len({i.filename for i in entries}) != len(entries)
                    or required not in archive.namelist()
                    or "[Content_Types].xml" not in archive.namelist()
                ):
                    raise ValueError("Invalid Office document")
        mimes = WORKSPACE_FILE_MIMES if workspace else FILE_MIMES
        return cls(name, mimes[suffix], data)
